function maxActiveSectionsAfterTrade(s) {
  const runs = [];
  let ones = 0;
  let start = 0;
  for (let end = 1; end <= s.length; end++) {
    if (end === s.length || s[end] !== s[start]) {
      runs.push({ bit: s[start], length: end - start });
      if (s[start] === '1') {
        ones += end - start;
      }
      start = end;
    }
  }
  let best = 0;
  for (let i = 1; i + 1 < runs.length; i++) {
    if (runs[i].bit === '1') {
      const gain = runs[i - 1].length + runs[i + 1].length;
      best = Math.max(best, gain);
    }
  }
  return ones + best;
}

