function maxActiveSectionsAfterTrade(s) {
  // Try every legal trade on the padded string and count the '1's of the middle part.
  const padded = '1' + s + '1';
  const countOnes = text => text.slice(1, -1).split('').filter(c => c === '1').length;
  const blocks = (text, ch) => {
    const found = [];
    let i = 0;
    while (i < text.length) {
      if (text[i] !== ch) { i++; continue; }
      let j = i;
      while (j < text.length && text[j] === ch) j++;
      found.push([i, j]);
      i = j;
    }
    return found;
  };
  let best = countOnes(padded);
  for (const [a, b] of blocks(padded, '1')) {
    if (a === 0 || b === padded.length) continue;
    if (padded[a - 1] !== '0' || padded[b] !== '0') continue;
    const erased = padded.slice(0, a) + '0'.repeat(b - a) + padded.slice(b);
    for (const [c, d] of blocks(erased, '0')) {
      if (erased[c - 1] !== '1' || erased[d] !== '1') continue;
      const filled = erased.slice(0, c) + '1'.repeat(d - c) + erased.slice(d);
      best = Math.max(best, countOnes(filled));
    }
  }
  return best;
}

